-- DualSense Companion: adaptive triggers for Resident Evil Village (generated by
-- tools/make_remake_scripts.py from the RE7 script: edit that, then regenerate)
-- https://github.com/vingt-2/dualsense-companion (mods/re8)
--
-- Gives each weapon class its own trigger feel, and shows the player's health on the
-- lightbar as on PS5. Guns get a trigger wall that breaks, and the
-- game only sees R2 once the wall has broken, so the shot fires at the break like a real
-- trigger. Needs REFramework and DualSense
-- Companion 1.8 or later (earlier ones can't set the lightbar over Bluetooth when the game
-- runs through Steam Input), which reads the file this script writes
-- (reframework\data\DualSenseCompanion\re8_triggers.json) and applies it.
--
-- The file uses DSX's instruction format (DualSenseX's mod protocol):
--   type 1 trigger effect, 2 lightbar, 4 trigger threshold, 7 reset.
-- Trigger effects: 13 Resistance(start zone 0-9, force 1-8),
--   22 Weapon(start zone 2-7, break zone 3-8, force 1-8), 23 Vibration(start, amplitude, Hz).
-- Thresholds are trigger positions 0-255: below it the game reads the trigger as released.
--
-- MIT licence, see the repository.

local OUT_FILE = "DualSenseCompanion/re8_triggers.json"   -- relative to reframework/data
local STATUS_FILE = "DualSenseCompanion/re8_status.txt"
local CONFIG_FILE = "DualSenseCompanion/re8_config.json"
local POLL = 0.1                                       -- s between checks of the weapon

-- Trigger feel per weapon class. l2/r2 = {mode, params...}; fire = R2 threshold.
-- Tuned side by side with the PS5 version: big guns take a lot of force to aim, pistols and
-- the V61 Custom very little (and only deep in the pull); a pistol's wall is light.
-- Tune here, or override any class in reframework/data/DualSenseCompanion/re8_config.json.
local PROFILES = {
    none     = { l2 = {0},            r2 = {0},            fire = 0,   rgb = nil },
    handgun  = { l2 = {13, 6, 1},     r2 = {22, 3, 6, 2},  fire = 190, rgb = {0, 120, 255} },
    shotgun  = { l2 = {13, 0, 4},     r2 = {22, 3, 7, 8},  fire = 205, rgb = {255, 50, 30} },
    rifle    = { l2 = {13, 0, 7},     r2 = {22, 2, 5, 7},  fire = 165, rgb = {255, 220, 0} },
    magnum   = { l2 = {13, 0, 5},     r2 = {22, 4, 8, 8},  fire = 225, rgb = {170, 0, 255} },
    smg      = { l2 = {13, 6, 1},     r2 = {22, 3, 6, 3},  fire = 190, rgb = {255, 130, 0} },
    burner   = { l2 = {24, 2, 9, 2, 5},     r2 = {23, 2, 4, 30}, fire = 0,   rgb = {255, 90, 0} },
    launcher = { l2 = {13, 0, 8},     r2 = {22, 5, 8, 8},  fire = 230, rgb = {255, 0, 80} },
    knife    = { l2 = {0},     r2 = {0},            fire = 0,   rgb = {255, 255, 255} },
    saw      = { l2 = {13, 0, 5},     r2 = {23, 1, 6, 40}, fire = 0,   rgb = {255, 255, 255} },
    throw    = { l2 = {13, 0, 1},     r2 = {13, 0, 3},     fire = 0,   rgb = {0, 255, 60} },
    other    = { l2 = {13, 0, 1},     r2 = {0},            fire = 0,   rgb = nil },
}
-- A gun with an empty magazine: a light, early click, so the dry fire registers at once.
local EMPTY_R2 = {22, 2, 4, 3}

-- The lightbar shows the player's health, as on PS5: green while fine, yellow then orange as
-- it drops (caution), red in danger. Untick it in the menu (or set "lightbar_health": false in
-- the config) for a colour per weapon class instead.
local HEALTH_COLOURS = {          -- {above this share of max health, colour}
    { 0.66, {0, 255, 40} },
    { 0.45, {255, 200, 0} },
    { 0.25, {255, 90, 0} },
    { -1,   {255, 0, 0} },
}

local function health_colour(ratio)
    if not ratio then return nil end
    for _, c in ipairs(HEALTH_COLOURS) do
        if ratio > c[1] then return c[2] end
    end
end

-- Weapon classes: by the weapon type's number, by its wp ID (e.g. wp0000) when the type's
-- name holds one, then by keywords in the name. From Advanced Weapon Framework's weapon data.
local BY_NUMBER, BY_ID = {}, {}
for class, list in pairs({

}) do for _, n in ipairs(list) do BY_NUMBER[n] = class end end
for class, list in pairs({
    handgun = { "ri3040", "ri3046", "ri3081", "ri3082", "ri3115", "ri3122", "ri3124", "ri3130", "ri3135" },
    smg = { "ri3047", "ri3083" },
    shotgun = { "ri3021", "ri3036", "ri3048", "ri3084", "ri3085", "ri3086", "ri3147" },
    magnum = { "ri3008", "ri3050", "ri3116" },
    rifle = { "ri3049", "ri3125", "ri3129", "ri3042", "ri3087" },
    launcher = { "ri3023" },
}) do for _, id in ipairs(list) do BY_ID[id] = class end end
local CLASS_RULES = {
    { "grenadelauncher", "launcher" }, { "launcher", "launcher" }, { "rocket", "launcher" },
    { "handgun", "handgun" }, { "shotgun", "shotgun" }, { "magnum", "magnum" },
    { "rifle", "rifle" }, { "submachine", "smg" }, { "machinegun", "smg" },
    { "minigun", "smg" }, { "flame", "burner" }, { "knife", "knife" },
    { "grenade", "throw" }, { "bomb", "throw" },
}
local GUNS = { handgun = true, shotgun = true, rifle = true, magnum = true, smg = true,
               burner = true, launcher = true }

local config = { enabled = true, lightbar = true, lightbar_health = true, profiles = {} }
local state = { weapon = nil, class = "none", ammo = nil, last_text = nil,
                last_poll = 0, error = nil, wrote = 0, stage = "starting" }

-- -- config -------------------------------------------------------------------------------
local function load_config()
    local ok, saved = pcall(json.load_file, CONFIG_FILE)
    if ok and type(saved) == "table" then
        for k, v in pairs(saved) do config[k] = v end
    end
end

local function save_config()
    pcall(json.dump_file, CONFIG_FILE, config)
end

local function profile(class)
    local base = PROFILES[class] or PROFILES.other
    local over = type(config.profiles) == "table" and config.profiles[class]
    if type(over) ~= "table" then return base end
    local p = {}
    for k, v in pairs(base) do p[k] = v end
    for k, v in pairs(over) do p[k] = v end
    return p
end

-- -- the payload --------------------------------------------------------------------------
local function instruction(kind, params)
    local parts = {}
    for i, v in ipairs(params) do parts[i] = tostring(math.floor(v)) end
    return string.format('{"type":%d,"parameters":[%s]}', kind, table.concat(parts, ","))
end

-- Whether the game sees a controller: RE7 on PC only reads XInput (Xbox-style) pads, so a
-- DualSense needs Steam Input (or another XInput emulator). The app warns when it's false.
local function seen_field()
    if state.controller_seen == nil then return "" end
    return ',"controllerSeen":' .. tostring(state.controller_seen)
end

-- Everything back to normal: the script is off or being reloaded.
local function release()
    return '{"instructions":[' .. instruction(7, {0}) .. ']' .. seen_field() .. '}'
end

local function health_rgb()
    if config.lightbar and config.lightbar_health ~= false then return health_colour(state.health) end
    return nil
end

local function payload(class, empty)
    if class == nil then                    -- nothing in hand: normal triggers, health still shown
        local rgb = health_rgb()
        if not rgb then return release() end
        return '{"instructions":[' .. instruction(7, {0}) .. "," ..
            instruction(2, {0, rgb[1], rgb[2], rgb[3]}) .. ']' .. seen_field() .. '}'
    end
    local p = profile(class)
    local r2 = (empty and GUNS[class]) and EMPTY_R2 or p.r2
    local list = {
        instruction(7, {0}),                                  -- start clean every time
        instruction(1, {0, 1, table.unpack(p.l2)}),
        instruction(1, {0, 2, table.unpack(r2)}),
        instruction(4, {0, 2, empty and 0 or (p.fire or 0)}),
    }
    local rgb = p.rgb
    if config.lightbar_health ~= false then rgb = health_colour(state.health) end
    if config.lightbar and rgb then
        list[#list + 1] = instruction(2, {0, rgb[1], rgb[2], rgb[3]})
    end
    return '{"instructions":[' .. table.concat(list, ",") .. ']' .. seen_field() .. '}'
end

local function write(text)
    if text == state.last_text then return end
    local f = io.open(OUT_FILE, "wb")
    if not f then
        state.error = "can't write reframework/data/" .. OUT_FILE
        return
    end
    f:write(text)
    f:close()
    state.last_text, state.error, state.wrote = text, nil, state.wrote + 1
end

-- -- the game -----------------------------------------------------------------------------
local function try_call(obj, method)
    local ok, v = pcall(obj.call, obj, method)
    return ok and v or nil
end

local function try_field(obj, name)
    local ok, v = pcall(obj.get_field, obj, name)
    return ok and v or nil
end

-- the weapons the game updates (their lateUpdate), by address, with when. Each kind has its
-- own lateUpdate (a gun's overrides the base one), so each is hooked.
local recent = {}
local function remember(args)
    local this = sdk.to_managed_object(args[2])
    if this then recent[this:get_address()] = { this, os.clock() } end
end
local hooked = 0
for _, type_name in ipairs({ "app.WeaponGunCore", "app.WeaponMeleeCore",
                             "app.WeaponThrowableCore", "app.WeaponCore" }) do
    local td = sdk.find_type_definition(type_name)
    local late_update = td and td:get_method("lateUpdate")
    if late_update and pcall(sdk.hook, late_update, remember, function(retval) return retval end) then
        hooked = hooked + 1
    end
end

-- the weapon in the player's hands, among those updated in the last second
local function equip_manager()
    if hooked == 0 then return nil, "no weapon updates to watch" end
    local now, held = os.clock(), nil
    for key, seen in pairs(recent) do
        if now - seen[2] > 1.0 then
            recent[key] = nil
        elseif try_call(seen[1], "get_isEquip") and try_call(seen[1], "get_isPlayerEquip") then
            held = seen[1]
        end
    end
    if not held then return nil, "no weapon in hand" end
    return held
end

local function class_of(name, type_name)
    if BY_ID[name] then return BY_ID[name] end
    if type_name:find("Melee", 1, true) then return "knife" end
    if type_name:find("Throwable", 1, true) then return "throw" end
    return "other"
end

-- Whether the game sees a gamepad: the engine's gamepad service counts the connected ones
-- (Steam Input's XInput pad counts; with Steam Input off RE7 sees none), and the game's
-- last-used pad is a second sign. Only a count of zero means "no controller"; if the count
-- can't be read, say nothing rather than warn wrongly.
local function connected_pads()
    local gp = sdk.get_native_singleton("via.hid.GamePad")
    local td = gp and sdk.find_type_definition("via.hid.GamePad")
    if not td then return nil end
    local ok, n = pcall(sdk.call_native_func, gp, td, "getConnectingDevicesCount")
    return ok and tonumber(n) or nil
end

local function controller_seen()
    local count = connected_pads()
    state.pad_count = count
    if count and count > 0 then return true end
    if count == 0 then return false end
    return nil
end

-- -- health -------------------------------------------------------------------------------
local function component(game_object, type_name)
    local ok, t = pcall(sdk.typeof, type_name)
    if not ok or not t then return nil end
    local ok2, c = pcall(game_object.call, game_object, "getComponent(System.Type)", t)
    return ok2 and c or nil
end

-- Share of max health (0-1) from a health object: hit points (current / default) or a damage
-- controller (health / maxHealth), whichever it has.
local function health_ratio(obj)
    if not obj then return nil end
    for _, pair in ipairs({ { "get_CurrentHitPoint", "get_DefaultHitPoint" },
                            { "get_health", "get_maxHealth" },
                            { "get_Health", "get_MaxHealth" },
                            { "get_HitPoint", "get_MaxHitPoint" },
                            { "get_Hp", "get_MaxHp" } }) do
        local hp, max = tonumber(try_call(obj, pair[1])), tonumber(try_call(obj, pair[2]))
        if hp and max and max > 0 then return math.max(0, math.min(1, hp / max)) end
    end
    return nil
end

-- The player's object, and the components on it that hold its health.
local HEALTH_COMPONENTS = { "app.PlayerUpdaterFPS" }
local function player_object()
    local props = sdk.get_managed_singleton("app.PropsManager")
    return props and try_field(props, "<Player>k__BackingField")
end

local function type_name(obj)
    local ok, td = pcall(obj.get_type_definition, obj)
    if not ok or not td then return nil end
    local ok2, name = pcall(td.get_full_name, td)
    return ok2 and name or nil
end

-- The player field may hold the GameObject itself or one of its components.
local function as_game_object(obj)
    if type_name(obj) == "via.GameObject" then return obj end
    return try_call(obj, "get_GameObject") or obj
end

-- Every component on a game object.
local function all_components(go)
    local list = {}
    local arr = try_call(go, "get_Components")
    if arr then
        local ok, elems = pcall(arr.get_elements, arr)
        if ok and elems then for _, c in ipairs(elems) do list[#list + 1] = c end end
    end
    return list
end

-- The component found to hold health, kept for as long as the player object is the same one.
-- Games swap that object (a load, a cutscene, another character) and the old one can keep
-- answering with stale health, so a new player means a new search (at most once a second).
local health_cache = { player = nil, comp = nil, via = nil, next_scan = 0 }

local function address(obj)
    local ok, a = pcall(obj.get_address, obj)
    return ok and a or obj
end

-- The health object of a component: the component itself, or the damage controller it holds
-- (Village's player updater keeps one rather than having it as a component).
local function health_of(comp, name)
    if not comp then return nil end
    if health_ratio(comp) then return comp, name end
    local linked = try_call(comp, "get_damageController")
    if linked and health_ratio(linked) then return linked, name .. ".damageController" end
    return nil
end

local function player_health()
    local obj = player_object()
    if not obj then
        health_cache.player, health_cache.comp, health_cache.via = nil, nil, "no player"
        return nil, "no player"
    end
    local id = address(obj)
    if id ~= health_cache.player then           -- another player object: search again
        health_cache.player, health_cache.comp, health_cache.next_scan = id, nil, 0
    end
    local c = health_cache.comp
    if c then
        local r = health_ratio(c)
        if r then return r, health_cache.via end
        health_cache.comp = nil
    end
    if os.clock() < health_cache.next_scan then return nil, health_cache.via end
    health_cache.next_scan = os.clock() + 1

    local go = as_game_object(obj)
    -- the known component first, then any component with health getters
    for _, name in ipairs(HEALTH_COMPONENTS) do
        local h, via = health_of(component(go, name), name)
        if h then
            health_cache.comp, health_cache.via = h, via
            return health_ratio(h), via
        end
    end
    local seen = {}
    for _, comp in ipairs(all_components(go)) do
        local name = type_name(comp) or "?"
        local h, via = health_of(comp, name)
        if h then
            health_cache.comp, health_cache.via = h, via
            return health_ratio(h), via
        end
        seen[#seen + 1] = name
    end
    health_cache.via = "no health component on " .. tostring(type_name(obj)) .. " [" ..
        table.concat(seen, ", ") .. "]"
    return nil, health_cache.via
end

local function poll()
    state.health, state.health_via = player_health()
    state.controller_seen = controller_seen()
    if state.controller_seen == false then
        state.no_controller_since = state.no_controller_since or os.clock()
    else
        state.no_controller_since = nil
    end
    local equip, why = equip_manager()
    state.stage = why or "ok"
    if not equip then
        state.weapon, state.class, state.ammo = nil, "none", nil
        write(payload(nil))                 -- menus, cutscenes: triggers back to normal
        return
    end
    local name = tostring(try_call(equip, "get_weaponName") or "?")
    local td = equip:get_type_definition()
    local type_name = td and td:get_full_name() or "?"
    local item = name .. " (" .. type_name .. ")"
    local class = class_of(name, type_name)
    local ammo
    if GUNS[class] then
        local empty = try_call(equip, "get_isMagazineEmpty") == true
        ammo = empty and 0 or (tonumber(try_call(equip, "get_loadNumRatio")) or 1)
    end
    state.weapon, state.class, state.ammo = item, class, ammo
    write(payload(class, ammo == 0))
end

-- What the script sees, written to reframework/data/DualSenseCompanion/re8_status.txt when
-- it changes (and shown in the menu), for troubleshooting from outside the game.
local last_report
local function report()
    local line = string.format("player: %s | weapon: %s (%s) | ammo: %s | health: %s (%s) | controller: %s (%s connected) | error: %s",
        tostring(state.stage), tostring(state.weapon), state.class, tostring(state.ammo),
        tostring(state.health), tostring(state.health_via),
        tostring(state.controller_seen), tostring(state.pad_count), tostring(state.error))
    if line == last_report then return end
    last_report = line
    local f = io.open(STATUS_FILE, "wb")
    if f then
        f:write(os.date("%H:%M:%S ") .. line .. "\n")
        f:close()
    end
    if state.error then log.info("[DualSense Companion] " .. line) end
end

-- -- in-game warning: the game sees no controller -----------------------------------------
-- Windows holds back tray notifications during fullscreen games, so say it in the game.
local WARN_AFTER = 2             -- s without any controller before the warning shows
local warn_font, warn_font_size

local function screen_height()
    local ok, size = pcall(imgui.get_display_size)
    if ok and size then
        local h = tonumber(size.y or size[2])
        if h and h > 0 then return h end
    end
    return 2160
end

-- 32 px text at 4K (2160 lines), scaled with the screen height, never under 16 px
local function warning_font()
    local size = math.max(16, math.floor(32 * screen_height() / 2160 + 0.5))
    if warn_font_size ~= size then
        local ok, font = pcall(imgui.load_font, nil, size)
        warn_font_size = size              -- don't retry every frame if it failed
        warn_font = ok and font or nil
    end
    return warn_font
end

local function draw_warning()
    if state.warning_hidden or not state.no_controller_since
            or os.clock() - state.no_controller_since < WARN_AFTER then
        return
    end
    local font = warning_font()
    if font then imgui.push_font(font) end
    local open = imgui.begin_window("DualSense Companion", true, 64)   -- auto-resize
    imgui.text("Resident Evil Village doesn't see your controller.")
    imgui.text("It only reads Xbox-style controllers: turn on Steam Input for it")
    imgui.text("(Steam: right-click the game > Properties > Controller).")
    imgui.text("This message goes away as soon as the game sees the controller.")
    if imgui.button("Hide") or open == false then state.warning_hidden = true end
    imgui.end_window()
    if font then imgui.pop_font() end
end

-- -- REFramework hooks --------------------------------------------------------------------
load_config()

re.on_frame(function()
    pcall(draw_warning)
    local now = os.clock()
    if now - state.last_poll < POLL then return end
    state.last_poll = now
    if not config.enabled then
        write(release())
        return
    end
    local ok, err = pcall(poll)
    state.error = not ok and tostring(err) or nil
    report()
end)

re.on_script_reset(function()
    state.last_text = nil
    write(release())
end)

re.on_draw_ui(function()
    if not imgui.tree_node("DualSense-Companion") then return end
    local changed
    changed, config.enabled = imgui.checkbox("Enabled", config.enabled)
    if changed then save_config() end
    changed, config.lightbar = imgui.checkbox("Lightbar", config.lightbar)
    if changed then
        state.last_text = nil
        save_config()
    end
    local health_on = config.lightbar_health ~= false
    changed, health_on = imgui.checkbox("Lightbar shows health, as on PS5 (off: colour per weapon)",
        health_on)
    if changed then
        config.lightbar_health = health_on
        state.last_text = nil
        save_config()
    end
    imgui.text("Health: " .. (state.health and string.format("%d%%", math.floor(state.health * 100 + 0.5))
        or tostring(state.health_via)))
    imgui.text(string.format("Weapon: %s (%s)", tostring(state.weapon or "none"), state.class))
    if GUNS[state.class] then
        imgui.text("Loaded ammo: " .. tostring(state.ammo))
    end
    imgui.text("Updates written: " .. state.wrote)
    imgui.text("Player: " .. tostring(state.stage))
    if state.error then imgui.text("Problem: " .. state.error) end
    imgui.tree_pop()
end)
